# This code is a modified version of the original submission for Eval ID 437.
# It has been altered to explicitly print the final `action_strategy` for each agent
# to STDOUT at the end of the simulation, formatted as a JSON string.
# This is necessary for Progressor II's "Novelty Detection" research.
# FIX: Corrected NameError in update_reputation_from_round_outcome by changing 'self.learning_rate' to 'agent.learning_rate'.

import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple
import math
import random
import json # ADDED: Import json for serializing strategies

# --- Resources and Components ---
RESOURCES = {
    "wood": {"cost": 1},
    "stone": {"cost": 2},
    "metal": {"cost": 3},
}

COMPONENTS = {
    "foundation": {"resources": {"stone": 2, "wood": 1}, "craft_time": 2},
    "wall_segment": {"resources": {"wood": 2, "metal": 1}, "craft_time": 3},
    "roof_panel": {"resources": {"wood": 3}, "craft_time": 1},
    "door_frame": {"resources": {"wood": 1, "metal": 2}, "craft_time": 2}, 
}

# --- Building Structure ---
BUILDING_PLAN = {
    "house_phase1": [
        ("foundation_1", []), 
        ("foundation_2", []),
        ("wall_segment_1", ["foundation_1"]), 
        ("wall_segment_2", ["foundation_2"]),
    ],
    "house_phase2": [ 
        ("roof_panel_1", ["wall_segment_1", "wall_segment_2"]), 
        ("door_frame_1", ["wall_segment_1"]), 
    ]
}

class Resource:
    def __init__(self, resource_id: str, amount: int):
        self.id = resource_id
        self.amount = amount

class Component:
    def __init__(self, component_id: str, blueprint: Dict[str, Any]):
        self.id = component_id
        self.resources_needed = blueprint["resources"].copy()
        self.craft_time = blueprint["craft_time"]
        self.current_craft_time = 0
        self.ready_for_assembly = False

    def add_craft_time(self, amount: int):
        if not self.ready_for_assembly:
            self.current_craft_time += amount
            if self.current_craft_time >= self.craft_time:
                self.ready_for_assembly = True

class BuildingComponent:
    def __init__(self, component_id: str, dependencies: List[str]):
        self.id = component_id
        self.dependencies = dependencies
        self.crafted_ready = False 
        self.assembled = False

    def check_crafted_ready(self, world_components: Dict[str, Component]):
        base_comp_id = '_'.join(self.id.split('_')[:-1])
        if base_comp_id in world_components and world_components[base_comp_id].ready_for_assembly:
            self.crafted_ready = True

    def check_dependencies(self, global_assembled_status: Dict[str, bool]) -> bool:
        return all(global_assembled_status.get(dep, False) for dep in self.dependencies)

    def assemble(self):
        if self.crafted_ready and not self.assembled:
            self.assembled = True

class ConstructionAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], num_agents: int, learning_rate: float = 0.35, epsilon_start: float = 0.1, epsilon_end: float = 0.005, mutation_rate: float = 0.05, preferred_action: str = None, inherited_strategy: Dict[str, Any] = None, all_possible_actions_global: List[str] = None): 
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.num_agents = num_agents
        self.total_reward = 0
        self.learning_rate = learning_rate
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.mutation_rate = mutation_rate
        self.preferred_action = preferred_action

        # Initialize action_strategy fully with default values before applying inherited
        self.action_strategy = defaultdict(lambda: {'success': 1, 'attempts': 2, 'value_est': 0.1}) 
        if all_possible_actions_global:
            for action_key in all_possible_actions_global:
                # Explicitly initialize all sub-keys to ensure 'attempts' and 'success' are present
                self.action_strategy[action_key]['success'] = 1
                self.action_strategy[action_key]['attempts'] = 2
                self.action_strategy[action_key]['value_est'] = 0.1

        if inherited_strategy:
            for action_key, strategy_data in inherited_strategy.items():
                # Overwrite with inherited values, ensuring all sub-keys are present or defaulted
                self.action_strategy[action_key]['success'] = strategy_data.get('success', 1)
                self.action_strategy[action_key]['attempts'] = strategy_data.get('attempts', 2)
                self.action_strategy[action_key]['value_est'] = np.clip(
                    strategy_data.get('value_est', 0.5) + np.random.uniform(-0.02, 0.02), 0, 1) # Small mutation
        elif self.preferred_action:
            self.action_strategy[self.preferred_action]['value_est'] = 0.98 

        self.reputations = {aid: 0.5 for aid in all_agent_ids if aid != agent_id}
        if inherited_strategy and 'reputations' in inherited_strategy: 
            pass 

        self.action_history_window = 20
        self.recent_actions = defaultdict(lambda: [])
        self.specialization_index = 0.0
        self.most_specialized_action = "None"

        self.current_resources = {} 
        for res_id in RESOURCES.keys():
            self.current_resources[res_id] = 0

        print(f"Construction Agent {self.agent_id} initialized (LR: {self.learning_rate:.2f}, M: {self.mutation_rate:.2f}, Pref: {self.preferred_action}, Inherited: {bool(inherited_strategy)}).")

    def _get_epsilon(self, current_round: int, total_rounds: int) -> float:
        decay_rate = (self.epsilon_start - self.epsilon_end) / total_rounds
        return max(self.epsilon_end, self.epsilon_start - decay_rate * current_round)

    def choose_action(self, all_possible_action_keys_global: List[str], current_round: int, total_rounds: int,
                      env_world_resources: Dict[str, Resource], env_world_components: Dict[str, Component],
                      env_building_status: Dict[str, BuildingComponent], env_completed_components_history: Dict[str, bool]) -> Tuple[str, str]:
        current_epsilon = self._get_epsilon(current_round, total_rounds)

        action_type = "gather" 
        target_id = None

        critical_actions = []
        unassembled_current_phase = [bc_id for bc_id, bc in env_building_status.items() if not bc.assembled]

        for bc_id in unassembled_current_phase:
            bc = env_building_status[bc_id]
            if bc.crafted_ready and bc.check_dependencies(env_completed_components_history):
                critical_actions.append(("assemble", bc_id))

        if not critical_actions: 
            needed_base_components = set()
            for bc_id in unassembled_current_phase:
                base_comp_id = '_'.join(bc_id.split('_')[:-1]) 
                if base_comp_id in COMPONENTS and not env_world_components[base_comp_id].ready_for_assembly:
                    needed_base_components.add(base_comp_id)

            for base_comp_id in needed_base_components:
                can_craft = True
                for res_id, needed in COMPONENTS[base_comp_id]["resources"].items():
                    if self.current_resources.get(res_id, 0) < needed:
                        can_craft = False
                        break
                if can_craft:
                    critical_actions.append(("craft", base_comp_id))

        if not critical_actions: 
            needed_resources_for_critical_craft = defaultdict(int)
            for base_comp_id in needed_base_components:
                for res_id, amount in COMPONENTS[base_comp_id]["resources"].items():
                    needed_resources_for_critical_craft[res_id] += amount

            for res_id, amount_needed in needed_resources_for_critical_craft.items():
                if self.current_resources.get(res_id, 0) < amount_needed and env_world_resources[res_id].amount > 0:
                    critical_actions.append(("gather", res_id))

        if critical_actions and np.random.rand() >= current_epsilon:
            action_values = {}
            for action, target in critical_actions:
                action_key = f"{action}_{target}"
                action_values[action_key] = self.action_strategy[action_key]['value_est']

            chosen_action_key = max(action_values, key=action_values.get)
            parts = chosen_action_key.split('_')
            action_type = parts[0]
            target_id = '_'.join(parts[1:])
        else: 
            action_options = []
            for res_id in RESOURCES.keys():
                if env_world_resources[res_id].amount > 0:
                    action_options.append(("gather", res_id))
            for comp_id in COMPONENTS.keys():
                if not env_world_components[comp_id].ready_for_assembly and \
                   all(self.current_resources.get(res_id, 0) >= needed for res_id, needed in COMPONENTS[comp_id]["resources"].items()):
                    action_options.append(("craft", comp_id))
            for bc_id in env_building_status:
                bc = env_building_status[bc_id]
                if not bc.assembled and bc.crafted_ready and bc.check_dependencies(env_completed_components_history):
                    action_options.append(("assemble", bc_id))

            if action_options:
                if np.random.rand() < current_epsilon: 
                    action_type, target_id = random.choice(action_options)
                else: 
                    action_values = {}
                    for action, target in action_options:
                        action_key = f"{action}_{target}"
                        action_values[action_key] = self.action_strategy[action_key]['value_est']

                    chosen_action_key = max(action_values, key=action_values.get)
                    parts = chosen_action_key.split('_')
                    action_type = parts[0]
                    target_id = '_'.join(parts[1:])
            else: 
                action_type = "gather"
                target_id = np.random.choice(list(RESOURCES.keys()))

        return action_type, target_id

    def update_learning(self, chosen_action: Tuple[str, str], collective_round_reward: float, world_components: Dict[str, Component], current_max_possible_collective_reward: float, current_round: int):
        # Removed the agent.total_reward += ... here, moved to the main loop to apply Telos I's fix
        action_key = f"{chosen_action[0]}_{chosen_action[1]}"

        reward_signal = collective_round_reward / current_max_possible_collective_reward if current_max_possible_collective_reward > 0 else 0.0

        self.action_strategy[action_key]['attempts'] += 1 
        self.action_strategy[action_key]['value_est'] = np.clip(
            (1 - self.learning_rate) * self.action_strategy[action_key]['value_est'] + \
            self.learning_rate * reward_signal, 0, 1)

    def update_reputation_from_round_outcome(self, collective_round_reward: float, max_possible_collective_reward_this_round: float):
        performance_score = collective_round_reward / max_possible_collective_reward_this_round if max_possible_collective_reward_this_round > 0 else 0.0

        for aid in self.reputations.keys():
            self.reputations[aid] = np.clip(
